let contextTarget=null;
function closeContextMenu(){$("contextMenu").classList.remove("open");contextTarget=null;}
function cycleEarthRelation(v){return v==="AUTO"?"FRONT_OF_EARTH":v==="FRONT_OF_EARTH"?"BEHIND_EARTH":"AUTO";}
