function openContextMenu(target,x,y){contextTarget=target;const point=target?.type==="point",curve=target?.type==="curve",earthTarget=target?.type==="earth";$("contextAdd").classList.toggle("hidden",!curve);$("contextDuplicate").classList.toggle("hidden",!point);$("contextDelete").classList.toggle("hidden",!point);$("contextEarthRelation").classList.toggle("hidden",!point);$("contextContact").classList.toggle("hidden",!point);$("contextEarthLock").classList.toggle("hidden",!earthTarget);if(point){selected=target.index;const p=pts[selected];$("contextDelete").disabled=selected===0||selected===pts.length-1||pts.length<=7;$("contextEarthRelation").textContent=`Earth: ${p.earth==="FRONT_OF_EARTH"?"FRONT":p.earth==="BEHIND_EARTH"?"BEHIND":"AUTO"}`;$("contextContact").textContent=`Contact: ${p.contact.replace("TOUCHING_EARTH","TOUCHING")}`;syncAllUI();draw();}if(earthTarget)$("contextEarthLock").textContent=earth.locked?"Unlock Earth":"Lock Earth";const menu=$("contextMenu");menu.classList.add("open");const mw=176,mh=220;menu.style.left=clamp(x+6,6,W-mw-6)+"px";menu.style.top=clamp(y+6,6,H-Math.min(mh,H-12)-6)+"px";}
$("contextAdd").onclick=()=>{const target=contextTarget;if(target?.type==="curve")mutate(()=>insertPointAtLocation(target.loc));closeContextMenu();};$("contextDuplicate").onclick=()=>{if(contextTarget?.type==="point")mutate(duplicateSelectedPoint);closeContextMenu();};$("contextDelete").onclick=()=>{if(contextTarget?.type==="point"&&selected>0&&selected<pts.length-1&&pts.length>7)mutate(deleteSelectedPoint);closeContextMenu();};$("contextEarthRelation").onclick=()=>{if(contextTarget?.type==="point"&&selected>=0)mutate(()=>pts[selected].earth=cycleEarthRelation(pts[selected].earth));closeContextMenu();};$("contextContact").onclick=()=>{if(contextTarget?.type==="point"&&selected>=0)mutate(()=>pts[selected].contact=cycleContact(pts[selected].contact));closeContextMenu();};$("contextEarthLock").onclick=()=>{mutate(()=>earth.locked=!earth.locked);closeContextMenu();};
function contextHit(x,y){const p=nearestPoint(x,y);if(p>=0)return{type:"point",index:p};const loc=nearestCurveLocation(x,y);if(loc)return{type:"curve",loc};if(hitEarth(x,y))return{type:"earth"};return null;}

const pointers=new Map();
let dragState=null,gesture=null,longPressTimer=0,longPressOrigin=null;
function cancelLongPress(){clearTimeout(longPressTimer);longPressTimer=0;longPressOrigin=null;}
function scheduleLongPress(target,x,y,pointerId){cancelLongPress();if(!target)return;longPressOrigin={x,y,pointerId,target};longPressTimer=setTimeout(()=>{const o=longPressOrigin;if(!o||!pointers.has(pointerId))return;if(o.target.type==="curve"){mutate(()=>insertPointAtLocation(o.target.loc));dragState={kind:"context",pointerId};}else{const before=dragState?.pointerId===pointerId?dragState.before:null;openContextMenu(o.target,x,y);dragState={kind:"context",pointerId,before};}cancelLongPress();},500);}
function pointerPos(e){return{x:e.clientX,y:e.clientY};}
function beginGesture(){cancelLongPress();if(dragState?.before)commit(dragState.before);dragState=null;const arr=[...pointers.values()];if(arr.length<2)return;const a=arr[0],b=arr[1],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},dist=Math.hypot(a.x-b.x,a.y-b.y)||1;gesture={startZoom:viewZoom,startDist:dist,worldX:(mid.x-cx-viewX)/(baseScale*viewZoom),worldY:-(mid.y-cy-viewY)/(baseScale*viewZoom)};}
function updateGesture(){if(!gesture||pointers.size<2)return;const arr=[...pointers.values()],a=arr[0],b=arr[1],mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2},dist=Math.hypot(a.x-b.x,a.y-b.y)||1;viewZoom=clamp(gesture.startZoom*dist/gesture.startDist,.35,4);viewX=mid.x-cx-gesture.worldX*baseScale*viewZoom;viewY=mid.y-cy+gesture.worldY*baseScale*viewZoom;syncViewportUI();draw();}
function finishDrag(){cancelLongPress();if(dragState?.before)commit(dragState.before);dragState=null;syncAllUI();}
canvas.addEventListener("pointerdown",e=>{if(e.button===2)return;closeContextMenu();$("menu").classList.remove("open");canvas.setPointerCapture?.(e.pointerId);pointers.set(e.pointerId,{...pointerPos(e),pointerType:e.pointerType});if(pointers.size===2){beginGesture();e.preventDefault();return;}if(pointers.size>2){e.preventDefault();return;}const{x,y}=pointerPos(e),forcePan=e.button===1||spaceHeld;if(forcePan){dragState={kind:"pan",pointerId:e.pointerId,lastX:x,lastY:y};e.preventDefault();return;}if(e.button!==0){e.preventDefault();return;}const point=nearestPoint(x,y),earthHit=hitEarth(x,y),curve=nearestCurveLocation(x,y),target=point>=0?{type:"point",index:point}:(!earth.locked&&earthHit)?{type:"earth"}:curve?{type:"curve",loc:curve}:earthHit?{type:"earth"}:null;if(mode==="edit"){if(point>=0){selected=point;dragState={kind:"point",pointerId:e.pointerId,lastX:x,lastY:y,startX:x,startY:y,before:sceneState()};syncAllUI();draw();scheduleLongPress(target,x,y,e.pointerId);}else if(!earth.locked&&earthHit){dragState={kind:"earth",pointerId:e.pointerId,lastX:x,lastY:y,startX:x,startY:y,before:sceneState()};scheduleLongPress({type:"earth"},x,y,e.pointerId);}else{dragState={kind:"pending",pointerId:e.pointerId,lastX:x,lastY:y,startX:x,startY:y};scheduleLongPress(target,x,y,e.pointerId);}}else if(mode==="move")dragState={kind:"snake",pointerId:e.pointerId,lastX:x,lastY:y,startX:x,startY:y,before:sceneState()};else dragState={kind:"pan",pointerId:e.pointerId,lastX:x,lastY:y,startX:x,startY:y};e.preventDefault();});
canvas.addEventListener("pointermove",e=>{if(!pointers.has(e.pointerId))return;const{x,y}=pointerPos(e);pointers.set(e.pointerId,{x,y,pointerType:e.pointerType});if(pointers.size>=2){updateGesture();e.preventDefault();return;}if(!dragState||dragState.pointerId!==e.pointerId)return;const dx=x-dragState.lastX,dy=y-dragState.lastY,total=Math.hypot(x-(dragState.startX??x),y-(dragState.startY??y));if(total>9)cancelLongPress();dragState.lastX=x;dragState.lastY=y;const s=currentScale(),wx=dx/s,wy=-dy/s;if(dragState.kind==="point"&&selected>=0){pts[selected].x+=wx;pts[selected].y+=wy;}else if(dragState.kind==="snake")for(const p of pts){p.x+=wx;p.y+=wy;}else if(dragState.kind==="earth"){earth.x+=wx;earth.y+=wy;}else if(dragState.kind==="pan"){viewX+=dx;viewY+=dy;}else return;syncAllUI();draw();e.preventDefault();});
function endPointer(e){pointers.delete(e.pointerId);if(gesture){if(pointers.size<2){gesture=null;dragState=null;scheduleAutosave();}e.preventDefault();return;}if(dragState?.pointerId===e.pointerId){if(dragState.kind==="pending"&&!longPressTimer){/* long press already handled */}else if(dragState.kind==="pending"){cancelLongPress();selected=-1;syncAllUI();draw();}finishDrag();}cancelLongPress();e.preventDefault();}
canvas.addEventListener("pointerup",endPointer);canvas.addEventListener("pointercancel",endPointer);
canvas.addEventListener("contextmenu",e=>{e.preventDefault();const target=contextHit(e.clientX,e.clientY);if(target)openContextMenu(target,e.clientX,e.clientY);else closeContextMenu();});
canvas.addEventListener("dblclick",e=>{if(mode!=="edit")return;if(nearestPoint(e.clientX,e.clientY)>=0)return;const loc=nearestCurveLocation(e.clientX,e.clientY);if(loc)mutate(()=>insertPointAtLocation(loc));});
canvas.addEventListener("wheel",e=>{e.preventDefault();closeContextMenu();if(e.shiftKey){const pan=Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY;viewX-=pan;draw();scheduleAutosave();return;}const factor=Math.exp(-e.deltaY*.0015);zoomAt(e.clientX,e.clientY,viewZoom*factor);},{passive:false});

function formFocused(){const a=document.activeElement;return !!a&&(a.tagName==="INPUT"||a.tagName==="TEXTAREA"||a.tagName==="SELECT"||a.isContentEditable);}
let keyNudgeBefore=null;
function finishKeyNudge(){if(!keyNudgeBefore)return;commit(keyNudgeBefore);keyNudgeBefore=null;syncAllUI();}
addEventListener("keydown",e=>{if(formFocused())return;const key=e.key.toLowerCase(),mod=e.metaKey||e.ctrlKey;if(mod&&key==="z"){e.preventDefault();finishKeyNudge();if(e.shiftKey)redo();else undo();return;}if(e.key===" "){spaceHeld=true;e.preventDefault();return;}if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.key)&&selected>=0){e.preventDefault();if(!keyNudgeBefore)keyNudgeBefore=sceneState();const step=e.shiftKey?.10:.02;if(e.key==="ArrowLeft")pts[selected].x-=step;else if(e.key==="ArrowRight")pts[selected].x+=step;else if(e.key==="ArrowUp")pts[selected].y+=step;else pts[selected].y-=step;syncAllUI();draw();return;}if(key==="e"){finishKeyNudge();setMode("edit");return;}if(key==="m"){finishKeyNudge();setMode("move");return;}if(key==="p"){finishKeyNudge();setMode("pan");return;}if(e.key==="Delete"||e.key==="Backspace"){finishKeyNudge();if(selected>0&&selected<pts.length-1&&pts.length>7){e.preventDefault();mutate(deleteSelectedPoint);}return;}if(e.key==="+"||e.key==="="){finishKeyNudge();e.preventDefault();zoomAt(W/2,H/2,viewZoom*1.12);return;}if(e.key==="-"||e.key==="_"){finishKeyNudge();e.preventDefault();zoomAt(W/2,H/2,viewZoom/1.12);return;}if(e.key==="Escape"){finishKeyNudge();closeContextMenu();$("menu").classList.remove("open");$("overlay").style.display="none";}});
addEventListener("keyup",e=>{if(e.key===" ")spaceHeld=false;if(["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.key))finishKeyNudge();});
function cancelActiveInput(){finishKeyNudge();cancelLongPress();if(dragState?.before)commit(dragState.before);pointers.clear();dragState=null;gesture=null;spaceHeld=false;syncAllUI();}
addEventListener("blur",cancelActiveInput);
document.addEventListener("visibilitychange",()=>{if(document.hidden)cancelActiveInput();});

