$("export").onclick=()=>openJSON("export");$("import").onclick=()=>openJSON("import");$("copyOverlay").onclick=async()=>{try{await navigator.clipboard.writeText($("jsonBox").value);}catch(err){$("jsonBox").focus();$("jsonBox").select();document.execCommand("copy");}};$("applyImport").onclick=()=>{try{const before=sceneState();importData(JSON.parse($("jsonBox").value));commit(before);$("overlay").style.display="none";}catch(err){alert("Could not import that JSON.");}};
